    '한눈에 보는 강조': ' Emphasis at a glance',
    'HCI의 정의와 발전': ' HCI definition and evolution',
    '디지털 헬스 · DBM · DTx': ' Digital health · DBM · DTx',
    '사용자 경험의 세 원리': ' Three user experience principles',
    '분석 · 기획 · 설계 · 평가': ' Analysis · Planning · Design · Evaluation',
