    '학습용 복습 질문입니다. 먼저 내 말로 답한 뒤 핵심어와 이유를 대조하세요.':
      ' These are study review questions. Answer in your own words first, then compare key terms and reasoning.',
    '01. 감각적·판단적·구성적 경험을 조절 개념과 함께 설명하세요.':
      ' 01. Explain sensory, judgmental, and compositional experience with their regulating concepts.',
    '감각적 경험은': ' Connect sensory experience with ',
    ', 판단적 경험은': ', judgmental experience with ',
    ', 구성적 경험은': ', and compositional experience with ',
    '로 연결합니다. 각각 센스 있는·가치 있는·조화로운 경험을 목표로 하며 하나의 통합된 경험을 분석하는 관점입니다.':
      '. They aim for fitting sensory, valuable, and harmonious experiences, respectively, and are perspectives for analyzing one integrated experience.',
    '02. 생동감의 깊이·넓이와 상호성의 세 요소를 구분하세요.':
      ' 02. Distinguish vividness depth and breadth from the three elements of interactivity.',
    '깊이는 한 감각 채널의 자극 수준, 넓이는 감각 채널 수입니다. 상호성은':
      ' Depth is the stimulation level within one sensory channel; breadth is the number of sensory channels. Interactivity is examined through ',
    '반응 속도·상호작용 범위·매핑': ' response speed, interaction range, and mapping',
    '으로 살펴봅니다. 매핑은 조작과 실제 행동·결과 사이의 자연스러운 대응입니다.':
      '. Mapping is the natural correspondence between an operation and actual behavior or results.',
    '03. 내재적·외재적 기인점과 목적·절차 요인을 연결하세요.':
      ' 03. Connect intrinsic and extrinsic loci of causality with purpose and procedure factors.',
    '내재적은 자기 원인·통제와 경험 자체의 목표, 외재적은 외부 원인·목표·보상으로 설명됩니다.':
      ' Intrinsic concerns internal causes and control and the experience itself as a goal; extrinsic concerns external causes, goals, and rewards.',
    '목적 요인': ' Purpose factors',
    '은 경험적·수단적 가치,': ' concern experiential and instrumental value, while',
    '절차 요인': ' procedure factors',
    '은 사용자·시스템 주도성입니다. 어느 기인점이 언제나 우월한 것은 아닙니다.':
      ' concern user and system initiative. Neither locus is always superior.',
    '04. 관계의 밀도와 강도는 무엇이 다른가요?':
      ' 04. How do relationship density and strength differ?',
    '밀도는 실제로 연결된 관계의 정도, 강도는 한 관계에서 상호작용하는 빈도·기간·정보량과 깊이입니다. 둘은 관계의 복잡도를 조절하며, 구성원 수만으로 복잡도를 판단할 수 없습니다.':
      ' Density is the extent of actual connections, while strength concerns interaction frequency, duration, information volume, and depth within a relationship. Both regulate relationship complexity, which cannot be judged from headcount alone.',
    '05. 3차원 경험 모형을 사용할 때 주의할 점은?':
      ' 05. What should you watch for when using the three-dimensional experience model?',
    원본의: ' First check the source’s',
    '대응을 먼저 확인합니다. 사용자 유형별로 분석하고 서로 다른 유형을 평균내지 않습니다. −5~+5는 예시로 정한 상대적 척도이며, 수치보다 방향과 강도에 주목합니다. 서로 다른 좌표 예시의 순서를 섞지 않습니다.':
      ' mapping. Analyze each user type separately without averaging different types. The −5 to +5 scale is relative and defined through examples; focus on direction and magnitude more than numbers. Do not mix the order used in different coordinate examples.',
    '06. SET의 세 요인과 경험 차원의 관계를 설명하세요.':
      ' 06. Explain the relationship between the three SET factors and experience dimensions.',
    '사회·문화적(S), 경제적(E), 기술적(T) 환경을 분석합니다. 각 환경 요인은 감각·판단·구성 모두에 영향을 줄 수 있으므로 일대일로 대응시키지 않습니다. 예를 들어 비용 변화는 서비스 접근과 목표 가치, 연결 관계에 함께 영향을 줄 수 있습니다.':
      ' Analyze sociocultural (S), economic (E), and technological (T) environments. Each factor can affect sensory, judgmental, and compositional experience, so there is no one-to-one mapping. For example, cost changes can affect access, goal-related value, and relationships together.',
    '07. 목표 경험 설정의 네 단계와 최종 산출을 말해보세요.':
      ' 07. State the four stages of defining a target experience and the final output.',
    '현재 경험점 → 내적 갈등 → 외적 요인의 압력 → 미래 지향 경험점':
      ' Current experience point → Internal conflict → External pressure → Future-oriented experience point',
    '입니다. 최종적으로 사용자에게 제공할 경험을 명시하고 아키텍처·인터랙션·인터페이스 설계와 평가로 구체화합니다.':
      ' is the sequence. Finally, specify the experience to provide and make it concrete through architecture, interaction, interface design, and evaluation.',
    '08. AI가 도입되면 좋은 경험이 자동으로 만들어질까요?':
      ' 08. Does introducing AI automatically create a good experience?',
    '아닙니다. AI는 자극·반응을 동적으로 조절하고, 가치·주도성·관계를 바꿀 수 있습니다. 그러나 목표와 맥락에 맞는지, 사용자가 이해하고 조절할 수 있는지 확인해야 합니다. 자동화나 관계의 증가 자체가 목표는 아닙니다.':
      ' No. AI can dynamically adjust stimuli and responses and change value, initiative, and relationships. However, check its fit with goals and context and whether users can understand and control it. More automation or more relationships is not a goal in itself.',
