    'ADHD 아동이 스스로 정한 일상 과업을 반복 수행하고 습관을 형성하도록 지원. 원본은 부모 관계·자신감·시간 활용·사회성의 변화를 소개합니다.':
      ' Supports children with ADHD in repeatedly performing self-selected daily tasks and building habits. The source introduces changes in parent relationships, confidence, time use, and social skills.',
